:root { --s9: #a3005b; --s8: #e4007f; --s7: #f0339a; --s3: #f6b3d6; --s2: #fbd3e8; --s1: #fde8f3; --s0: #fff5fa; --ink: #1f1018; --ink2: #4a3340; --muted: #7a6370; --line: #ecd9e3; --line2: #f4e8ee; --ok: #15803d; --okbg: #dcfce7; --warn: #b45309; --warnbg: #fef3c7; --bad: #b91c1c; --badbg: #fee2e2; }body { font-family: "Noto Sans TC", "Microsoft JhengHei", system-ui, sans-serif; background: rgb(251, 246, 248); color: var(--ink); }.hidden { display: none !important; }.wrap { max-width: 1560px; }.nw { white-space: nowrap; }.sh { background: linear-gradient(100deg,#b8006a 0%,var(--s8) 55%,#ff4fa3 100%); color: rgb(255, 255, 255); border-bottom: 3px solid rgb(255, 208, 232); }.card { background: rgb(255, 255, 255); border: 1px solid var(--line2); border-radius: 12px; box-shadow: rgba(228, 0, 127, 0.06) 0px 1px 2px; }.btn { display: inline-flex; align-items: center; gap: 6px; padding: 8px 14px; border-radius: 8px; font-size: 14px; font-weight: 600; cursor: pointer; border: 1px solid transparent; white-space: nowrap; text-decoration: none; }.btn:disabled { opacity: 0.5; cursor: not-allowed; }.btn-p { background: var(--s8); color: rgb(255, 255, 255); }.btn-p:hover:not(:disabled) { background: var(--s9); }.btn-o { background: rgb(255, 255, 255); color: var(--s9); border-color: var(--s3); }.btn-o:hover:not(:disabled) { background: var(--s0); }.btn-sm { padding: 4px 10px; font-size: 12.5px; }.badge { display: inline-block; padding: 1px 8px; border-radius: 6px; font-size: 11.5px; font-weight: 600; white-space: nowrap; }.b-ok { background: var(--okbg); color: var(--ok); }.b-bad { background: var(--badbg); color: var(--bad); }.neg { color: var(--bad); }.b-dim { background: rgb(243, 237, 240); color: var(--muted); }.b-s { background: var(--s1); color: var(--s9); }.b-warn { background: var(--warnbg); color: var(--warn); }.b-blue { background: rgb(238, 242, 255); color: rgb(55, 48, 163); }table.t { width: 100%; border-collapse: separate; border-spacing: 0px; font-size: 13px; }table.t th { background: rgb(251, 240, 245); color: var(--ink2); font-weight: 600; font-size: 12px; padding: 8px 10px; text-align: left; white-space: nowrap; position: sticky; top: 0px; z-index: 2; border-bottom: 1px solid var(--line); }table.t td { padding: 7px 10px; border-bottom: 1px solid var(--line2); vertical-align: middle; }table.t td.num, table.t th.num { text-align: right; font-variant-numeric: tabular-nums; }table.t tr.og td { cursor: pointer; }table.t tr.og:hover td { background: var(--s0); }table.t tr.og td:first-child { box-shadow: inset 4px 0 0 var(--s3); }table.t tr.og.blk td:first-child, table.t tr.og.pend td:first-child { box-shadow: inset 4px 0 0 var(--bad); }table.t tr.og.sel td { background: var(--s1); }table.t tr.og.sel td:first-child { box-shadow: inset 4px 0 0 var(--s8); }.fn { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 11.5px; color: var(--ink2); }.inp { border: 1px solid var(--line); border-radius: 7px; padding: 5px 9px; font-size: 13px; background: rgb(255, 255, 255); }.inp:focus { outline: none; border-color: var(--s7); box-shadow: 0 0 0 2px var(--s1); }.tbl-wrap { overflow: auto; max-height: 70vh; border: 1px solid var(--line2); border-radius: 10px; background: rgb(255, 255, 255); }.muted { color: var(--muted); }.kbd { font-size: 11.5px; color: var(--muted); }.alert { border-radius: 10px; padding: 10px 14px; font-size: 13px; }.al-bad { background: var(--badbg); color: rgb(127, 29, 29); border: 1px solid rgb(254, 202, 202); }.al-warn { background: var(--warnbg); color: rgb(120, 53, 15); border: 1px solid rgb(253, 230, 138); }.chip { display: inline-flex; align-items: center; gap: 5px; padding: 4px 12px; border-radius: 999px; font-size: 13px; border: 1px solid var(--s3); background: rgb(255, 255, 255); color: var(--s9); cursor: pointer; user-select: none; }.chip.on { background: var(--s8); color: rgb(255, 255, 255); border-color: var(--s8); }.sum { display: flex; flex-wrap: wrap; gap: 8px 22px; align-items: baseline; }.sum span { white-space: nowrap; }.sum b { font-size: 18px; color: var(--s9); margin-right: 3px; }.ck { width: 16px; height: 16px; accent-color: var(--s8); cursor: pointer; vertical-align: middle; }.ck:disabled { cursor: not-allowed; }.prob { color: var(--bad); font-size: 12px; }.prob + .prob { margin-top: 2px; }.dzbox { display: flex; align-items: center; gap: 12px; border: 2px dashed var(--s3); border-radius: 12px; padding: 16px 18px; background: var(--s0); color: var(--s9); cursor: pointer; font-size: 13.5px; transition: border-color 0.15s, background 0.15s; }.dzbox:hover, .dzbox.over { border-color: var(--s8); background: var(--s1); }.dzbox > i { font-size: 26px; }.dzbox b { font-size: 14.5px; }.fresh { display: flex; flex-wrap: wrap; gap: 6px; justify-content: flex-end; }.fresh span { display: inline-flex; align-items: center; gap: 4px; border: 1px solid var(--line); background: rgb(255, 255, 255); border-radius: 999px; padding: 2px 10px; font-size: 12px; color: var(--ink2); white-space: nowrap; }.fresh span.w { border-color: rgb(253, 230, 138); background: var(--warnbg); color: var(--warn); }.pv { border: 1px solid var(--s2); border-radius: 12px; background: rgb(255, 255, 255); padding: 14px 16px; }table.t tr.og.ask td { background: rgb(255, 251, 235); }.help { border: 1px solid rgb(253, 230, 138); background: rgb(255, 253, 243); border-radius: 10px; padding: 10px 14px; font-size: 12.5px; color: var(--ink2); }.help li { margin: 3px 0px 3px 18px; list-style: disc; }.help b { color: var(--ink); }.pv h3 { font-weight: 700; font-size: 14.5px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }.facts { display: flex; flex-wrap: wrap; gap: 6px 18px; font-size: 13px; color: var(--ink2); margin-top: 6px; }.facts b { color: var(--ink); }.stages { display: flex; gap: 6px; align-items: stretch; }.stages .arr { align-self: center; color: rgb(220, 197, 209); font-size: 16px; }.st { flex: 1 1 0%; min-width: 0px; background: rgb(255, 255, 255); border: 1px solid var(--line); border-radius: 12px; padding: 9px 12px; cursor: pointer; transition: border-color 0.15s, background 0.15s; }.st:hover { border-color: var(--s3); }.st .n { font-size: 24px; font-weight: 800; line-height: 1.15; color: var(--s8); font-variant-numeric: tabular-nums; }.st.zero .n { color: rgb(212, 195, 204); }.st.bad .n { color: var(--bad); }.st.all .n { color: var(--ink2); }.st .t { font-size: 13.5px; font-weight: 700; }.st .d { font-size: 11.5px; color: var(--muted); margin-top: 1px; }.st.on { border: 2px solid var(--s8); background: var(--s0); padding: 8px 11px; box-shadow: rgba(228, 0, 127, 0.14) 0px 2px 10px; }.st.soon { cursor: default; background: repeating-linear-gradient(135deg, rgb(255, 255, 255) 0px, rgb(255, 255, 255) 10px, rgb(250, 245, 248) 10px, rgb(250, 245, 248) 20px); }.st.soon .n { color: rgb(212, 195, 204); }.layout { display: flex; align-items: flex-start; }#side { position: fixed; inset: 0px; z-index: 50; background: rgba(60, 8, 34, 0.45); display: flex; align-items: flex-start; justify-content: center; padding: 18px 14px; }#side.hidden { display: none; }body.side-open { overflow: hidden; }.sd-box { width: min(1420px, 100%); max-height: calc(-36px + 100vh); background: rgb(255, 255, 255); border-radius: 14px; box-shadow: rgba(60, 8, 34, 0.35) 0px 24px 70px; display: flex; flex-direction: column; overflow: hidden; }.sd-h { display: flex; align-items: flex-start; gap: 10px; padding: 14px 20px 12px; border-bottom: 1px solid var(--line2); background: var(--s0); }.sd-f { display: flex; align-items: center; gap: 8px; padding: 10px 20px; border-top: 1px solid var(--line); background: rgb(255, 255, 255); }.sd-x { background: transparent; border: 0px; font-size: 18px; color: var(--muted); cursor: pointer; padding: 2px 4px; }.sd-x:hover { color: var(--ink); }.sd-b { flex: 1 1 0%; overflow: auto; padding: 12px 20px 24px; }.sd-facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 8px; margin-top: 10px; }.sd-facts > div { border: 1px solid var(--line2); border-radius: 10px; padding: 6px 12px; background: rgb(255, 255, 255); }.sd-facts .k { font-size: 11.5px; color: var(--muted); }.sd-facts .v { font-size: 14px; font-weight: 700; }.sd-grid { column-gap: 12px; margin-top: 12px; }.sd-grid > .sd-sec { break-inside: avoid; margin: 0px 0px 12px; }.sd-log .sd-it { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 12px; padding: 6px 0px; }.sd-log .sd-it > div { margin: 0px; }.it-tools { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 2px 0px 8px; }table.it-t td { vertical-align: top; padding: 8px 9px; }table.it-t th { padding: 7px 9px; position: sticky; top: 0px; }table.it-t tr.sd-it td { border-top: 1px solid var(--line2); }table.it-t tr.sd-it.bad td { background: rgb(255, 246, 244); }table.it-t tr.sd-it.bad td:first-child { box-shadow: inset 4px 0 0 var(--bad); }table.it-t tr.sd-it.ask td { background: rgb(255, 251, 235); }table.it-t tr.sd-it.ask td:first-child { box-shadow: inset 4px 0 0 var(--warn); }table.it-t tr.sd-it.hit td:first-child { box-shadow: inset 4px 0 0 var(--s8); }table.it-t tr.sd-it.x td.xs { text-decoration: line-through; color: var(--muted); }table.it-t .big { font-size: 15px; font-weight: 700; }table.it-t .nm2 { min-width: 220px; max-width: 380px; }.sd-sec { border: 1px solid var(--line2); border-radius: 10px; margin-top: 10px; }.sd-sec > .h { display: flex; align-items: center; gap: 8px; padding: 8px 12px; font-weight: 700; font-size: 13.5px; }.sd-sec > .b { padding: 0px 12px 10px; }details.sd-sec > summary { list-style: none; cursor: pointer; }details.sd-sec > summary::-webkit-details-marker { display: none; }div.sd-it { padding: 9px 0px; border-top: 1px solid var(--line2); font-size: 13px; }div.sd-it:first-child { border-top: 0px; }.sd-kv { display: flex; flex-wrap: wrap; gap: 2px 14px; font-size: 12px; color: var(--ink2); margin-top: 3px; }.sd-kv b { color: var(--ink); }.abar { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; background: rgb(253, 242, 247); border: 1px solid rgb(243, 214, 229); border-radius: 10px; padding: 8px 12px; font-size: 13px; }.pick { position: relative; display: inline-block; }.pick-pop { position: absolute; z-index: 40; top: calc(100% + 4px); left: 0px; min-width: 200px; max-height: 320px; overflow: auto; background: rgb(255, 255, 255); border: 1px solid var(--line); border-radius: 10px; box-shadow: rgba(60, 10, 30, 0.18) 0px 12px 30px; padding: 6px 10px; font-size: 13px; }.pick-pop label { display: flex; gap: 8px; align-items: center; padding: 3px 0px; white-space: nowrap; cursor: pointer; }dialog { border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 14px; padding: 0px; width: min(580px, 96vw); max-height: 88vh; box-shadow: rgba(0, 0, 0, 0.35) 0px 30px 80px; }dialog::backdrop { background: rgba(31, 16, 24, 0.45); }.dh { display: flex; align-items: center; gap: 10px; padding: 12px 16px; background: var(--s8); color: rgb(255, 255, 255); font-weight: 700; }.dh .x { margin-left: auto; background: transparent; border: 0px; color: rgb(255, 255, 255); font-size: 18px; cursor: pointer; }.db { padding: 14px 16px; overflow: auto; max-height: calc(-52px + 88vh); }#toasts { position: fixed; right: 18px; top: 78px; z-index: 99; display: flex; flex-direction: column; gap: 8px; align-items: flex-end; }.toast { background: rgb(31, 16, 24); color: rgb(255, 255, 255); padding: 10px 14px; border-radius: 10px; font-size: 14px; box-shadow: rgba(0, 0, 0, 0.25) 0px 10px 30px; max-width: 560px; white-space: pre-line; }.toast.err { background: var(--bad); }.ver { text-align: right; padding: 4px 20px 14px; font-size: 11px; color: var(--muted); }.hbtn { display: inline-flex; align-items: center; gap: 6px; padding: 5px 12px; border-radius: 8px; font-size: 13px; font-weight: 700; color: rgb(255, 255, 255); background: rgba(255, 255, 255, 0.14); border: 1px solid rgba(255, 255, 255, 0.7); cursor: pointer; white-space: n