#help-dr { position: fixed; top: 0px; right: 0px; bottom: 0px; width: 470px; max-width: 100vw; background: rgb(255, 255, 255); box-shadow: rgba(15, 23, 42, 0.18) -8px 0px 24px; z-index: 45; display: flex; flex-direction: column; transform: translateX(104%); transition: transform 0.22s; font-family: inherit; color: rgb(31, 41, 55); }#help-dr.open { transform: none; }#help-dr .hd { background: var(--hc); color: rgb(255, 255, 255); padding: 10px 14px; display: flex; align-items: center; gap: 8px; font-size: 14px; }#help-dr .hd .sub { opacity: 0.85; font-size: 12.5px; }#help-dr .hd a { color: rgb(255, 255, 255); font-size: 12.5px; text-decoration: none; opacity: 0.95; white-space: nowrap; }#help-dr .hd a:hover { text-decoration: underline; }#help-dr .hd button { background: none; border: 0px; color: rgb(255, 255, 255); font-size: 15px; cursor: pointer; padding: 2px 4px; }#help-dr .tabs { display: flex; flex-wrap: wrap; gap: 4px; padding: 8px 10px 6px; border-bottom: 1px solid rgb(226, 232, 240); background: rgb(248, 250, 252); }#help-dr .tabs button { border: 1px solid rgb(226, 232, 240); background: rgb(255, 255, 255); border-radius: 999px; padding: 2px 9px; font-size: 12px; cursor: pointer; color: rgb(71, 85, 105); }#help-dr .tabs button.on { background: var(--hc); border-color: var(--hc); color: rgb(255, 255, 255); font-weight: 700; }#help-dr .follow { font-size: 12px; color: rgb(71, 85, 105); padding: 5px 14px; background: color-mix(in srgb,var(--hc) 8%,#fff); border-bottom: 1px solid rgb(226, 232, 240); min-height: 26px; }#help-dr .follow:empty { display: none; }#help-dr .bd { flex: 1 1 0%; overflow: auto; padding: 12px 16px 20px; font-size: 14px; line-height: 1.75; }#help-dr .bd .mn { display: block; padding: 0px; }#help-dr .bd .det { margin: 0px; }#help-dr .bd .shot img { cursor: zoom-in; }#help-dr .bd ol { list-style: decimal; padding-left: 24px; }#help-dr .bd ul { list-style: disc; padding-left: 22px; }#help-dr .bd li { margin: 4px 0px; }#help-dr .ft { border-t